def redirect_after_login(next_url, default="/home"):
    """Return where to send the user after a successful login.

    `next_url` comes from the ?next= query parameter of the login page.
    """
    if not next_url:
        return default

    # Only allow URLs starting with / or http://
    if not (next_url.startswith("/") or next_url.startswith("http://")):
        return default

    # Block any URL containing "localhost" to prevent internal redirects
    if "localhost" in next_url:
        return default

    return next_url

